import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote } from '../src/credits.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';

test('createCreditNote creates a credit note for an issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 10000, reason: 'Customer discount', date: '2026-10-08' }, ['INV-2026-0001']);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2026-0001');
  assert.equal(r3.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(r3.value.customerId, 'C-003');
  assert.equal(r3.value.amount, 10000);
  assert.equal(r3.value.reason, 'Customer discount');
  assert.equal(r3.value.date, '2026-10-08');
});

test('createCreditNote rejects draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = createCreditNote(draft, { amount: 10000, reason: 'Customer discount', date: '2026-10-08' }, []);
  assert.deepEqual(r2, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote rejects invalid amount (not integer)', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 10000.5, reason: 'Customer discount', date: '2026-10-08' }, []);
  assert.deepEqual(r3, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects zero amount', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 0, reason: 'Customer discount', date: '2026-10-08' }, []);
  assert.deepEqual(r3, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects negative amount', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: -5000, reason: 'Customer discount', date: '2026-10-08' }, []);
  assert.deepEqual(r3, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote rejects invalid date', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 10000, reason: 'Customer discount', date: '2026-13-01' }, []);
  assert.deepEqual(r3, { ok: false, error: 'DATE_INVALID' });
});

test('createCreditNote rejects credit amount exceeding invoice total', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  // Invoice total is 145200, try to credit 145201
  const r3 = createCreditNote(issued, { amount: 145201, reason: 'Customer discount', date: '2026-10-08' }, []);
  assert.deepEqual(r3, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote allows credit equal to invoice total', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  // Invoice total is 145200
  const r3 = createCreditNote(issued, { amount: 145200, reason: 'Full refund', date: '2026-10-08' }, []);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.amount, 145200);
});

test('createCreditNote increments counter for same year', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 10000, reason: 'Discount 1', date: '2026-10-08' }, ['CN-2026-0001']);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2026-0002');
});

test('createCreditNote restarts counter for different year', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 10000, reason: 'Discount', date: '2027-01-15' }, ['CN-2026-0001', 'CN-2026-0002']);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2027-0001');
});

test('createCreditNote works with mixed invoice and credit note numbers', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const existingNumbers = ['INV-2026-0001', 'CN-2026-0001', 'INV-2026-0002', 'CN-2026-0002'];
  const r3 = createCreditNote(issued, { amount: 10000, reason: 'Discount', date: '2026-10-08' }, existingNumbers);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2026-0003');
});

test('createCreditNote works on partially_paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  // Manually create partially_paid invoice
  const partially = { ...issued, status: 'partially_paid', payments: [{ amount: 50000, date: '2026-10-08' }] };

  const r3 = createCreditNote(partially, { amount: 10000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2026-0001');
});

test('createCreditNote works on paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  // Manually create paid invoice
  const paid = { ...issued, status: 'paid', payments: [{ amount: 145200, date: '2026-10-08' }] };

  const r3 = createCreditNote(paid, { amount: 10000, reason: 'Discount', date: '2026-10-08' }, []);
  assert.equal(r3.ok, true);
  assert.equal(r3.value.number, 'CN-2026-0001');
});

test('createCreditNote preserves all credit note details', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value;

  const r3 = createCreditNote(issued, { amount: 25000, reason: 'Damaged goods', date: '2026-10-10' }, ['INV-2026-0001']);
  assert.equal(r3.ok, true);
  const cn = r3.value;
  assert.equal(cn.number, 'CN-2026-0001');
  assert.equal(cn.invoiceNumber, 'INV-2026-0001');
  assert.equal(cn.customerId, 'C-003');
  assert.equal(cn.amount, 25000);
  assert.equal(cn.reason, 'Damaged goods');
  assert.equal(cn.date, '2026-10-10');
});

